import re

# The K-lineage sequence provided
dna_seq = ""

def translate(dna):
    table = {
        'ATA':'I', 'ATC':'I', 'ATT':'I', 'ATG':'M', 'ACA':'T', 'ACC':'T', 'ACG':'T', 'ACT':'T',
        'AAC':'N', 'AAT':'N', 'AAA':'K', 'AAG':'K', 'AGC':'S', 'AGT':'S', 'AGA':'R', 'AGG':'R',
        'CTA':'L', 'CTC':'L', 'CTG':'L', 'CTT':'L', 'CCA':'P', 'CCC':'P', 'CCG':'P', 'CCT':'P',
        'CAC':'H', 'CAT':'H', 'CAA':'Q', 'CAG':'Q', 'CGA':'R', 'CGC':'R', 'CGG':'R', 'CGT':'R',
        'GTA':'V', 'GTC':'V', 'GTG':'V', 'GTT':'V', 'GCA':'A', 'GCC':'A', 'GCG':'A', 'GCT':'A',
        'GAC':'D', 'GAT':'D', 'GAA':'E', 'GAG':'E', 'GGA':'G', 'GGC':'G', 'GGG':'G', 'GGT':'G',
        'TCA':'S', 'TCC':'S', 'TCG':'S', 'TCT':'S', 'TTC':'F', 'TTT':'F', 'TTA':'L', 'TTG':'L',
        'TAC':'Y', 'TAT':'Y', 'TAA':'_', 'TAG':'_', 'TGC':'C', 'TGT':'C', 'TGA':'_', 'TGG':'W',
    }
    protein = ""
    for i in range(0, len(dna), 3):
        codon = dna[i:i+3]
        protein += table.get(codon, '?')
    return protein

protein_seq = translate(dna_seq)
protein_seq=""
# Regex for N-glycosylation: Asn (N) - Not Proline - Ser (S) or Thr (T)
# We use a lookahead (?=...) to find overlapping sites if they exist
pattern = re.compile(r'N[^P][ST]')

print(f"{'Position':<10} {'Motif':<10}")
print("-" * 20)

for match in re.finditer(f'(?={pattern.pattern})', protein_seq):
    pos = match.start() -15 # 1-based indexing for biology
    motif = protein_seq[match.start():match.start()+3]
    print(f"{pos:<10} {motif:<10}")